SET LOCAL lock_timeout = '3s';

-- India's pincodes for the admin website's Leads page (districts and areas). Built by docs/tools/pincodes.py
-- from India Post's All India Pincode Directory (Department of Posts, data.gov.in, Government Open Data
-- Licence - India). Read-only reference data: the app never writes it.
--   places: post office names, delivery offices first; latitude/longitude: the middle of its offices (null if
--   none has a usable point: such a pincode can't be scanned); radius_m: how far the scan searches around it.
CREATE TABLE india_pincodes (
    pincode    VARCHAR(6)   PRIMARY KEY CHECK (pincode ~ '^[1-9][0-9]{5}$'),
    district   VARCHAR(80)  NOT NULL,
    state      VARCHAR(80)  NOT NULL,
    places     VARCHAR(200) NOT NULL,
    latitude   NUMERIC(9,6) CHECK (latitude BETWEEN 6 AND 37.6),
    longitude  NUMERIC(9,6) CHECK (longitude BETWEEN 68 AND 97.5),
    radius_m   INTEGER      NOT NULL CHECK (radius_m BETWEEN 500 AND 10000),
    CHECK ((latitude IS NULL) = (longitude IS NULL))
);





















